import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.io.IOException;

import static org.junit.Assert.assertEquals;

public class FileUtilsTest {

    @Rule
    public TemporaryFolder mTemporaryFolder = new TemporaryFolder();

    @Test
    public void getUniqueFileReturnsPreferredFileWhenAvailable() throws IOException {
        File preferredFile = new File(mTemporaryFolder.getRoot(), "document_encrypted.pdf");

        assertEquals(preferredFile, FileUtils.getUniqueFile(preferredFile));
    }

    @Test
    public void getUniqueFileAddsNumberWhenPreferredFileExists() throws IOException {
