    public void getUniqueFileSkipsExistingNumberedFiles() throws IOException {
        mTemporaryFolder.newFile("document_encrypted.pdf");
        mTemporaryFolder.newFile("document_encrypted1.pdf");
        mTemporaryFolder.newFile("document_encrypted2.pdf");
        File preferredFile = new File(mTemporaryFolder.getRoot(), "document_encrypted.pdf");

        assertEquals("document_encrypted3.pdf", FileUtils.getUniqueFile(preferredFile).getName());
    }
}

